//! Byte-for-byte conformance against `reference/vectors/03-sumcheck/`
//! (`mle.json`, `sumcheck.json`), generated by
//! `reference/gen_vectors_01_03.py`.

use std::path::PathBuf;

use om_field::K;
use om_sumcheck::{SumcheckProof, eq_table, mle_eval, sumcheck_prove, sumcheck_verify};
use om_transcript::Transcript;
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/03-sumcheck")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn k(v: &Value) -> K {
    K::from_hex(v.as_str().unwrap()).unwrap()
}

fn ks(v: &Value) -> Vec<K> {
    v.as_array().unwrap().iter().map(k).collect()
}

fn hexes(xs: &[K]) -> Vec<String> {
    xs.iter().map(|x| x.to_hex()).collect()
}

#[test]
fn mle_vectors() {
    let v = load("mle.json");
    let r = ks(&v["r"]);
    let table = ks(&v["table"]);
    assert_eq!(k(&v["mle_eval"]).to_hex(), mle_eval(&table, &r).to_hex());
    let expect: Vec<String> = v["eq_table"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap().to_string())
        .collect();
    assert_eq!(expect, hexes(&eq_table(&r)));
}

#[test]
fn sumcheck_vectors() {
    let v = load("sumcheck.json");
    for vec in v["vectors"].as_array().unwrap() {
        let degree = vec["degree"].as_u64().unwrap() as usize;
        let num_vars = vec["num_vars"].as_u64().unwrap() as usize;
        let protocol_label = vec["protocol_label"].as_str().unwrap().as_bytes();
        let label = vec["label"].as_str().unwrap().as_bytes();
        let tables: Vec<Vec<K>> = vec["tables"].as_array().unwrap().iter().map(ks).collect();
        let claim = k(&vec["claim"]);
        assert_eq!(
            tables.len(),
            degree,
            "summand is a product of `degree` tables"
        );
        let f = |vals: &[K]| vals.iter().fold(K::ONE, |a, &x| a * x);

        // The claim is the honest sum over the hypercube.
        let mut sum = K::ZERO;
        for i in 0..1 << num_vars {
            let vals: Vec<K> = tables.iter().map(|t| t[i]).collect();
            sum += f(&vals);
        }
        assert_eq!(claim.to_hex(), sum.to_hex(), "degree {degree} claim");

        // Prover output (messages, challenges, table evals) byte-for-byte.
        let mut pt = Transcript::new_default(protocol_label);
        let (proof, rs, evals) = sumcheck_prove(claim, tables, &f, degree, &mut pt, label);
        let expect_msgs: Vec<Vec<String>> = vec["round_msgs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|m| {
                m.as_array()
                    .unwrap()
                    .iter()
                    .map(|x| x.as_str().unwrap().to_string())
                    .collect()
            })
            .collect();
        let got_msgs: Vec<Vec<String>> = proof.round_msgs.iter().map(|m| hexes(m)).collect();
        assert_eq!(expect_msgs, got_msgs, "degree {degree} round msgs");
        assert_eq!(
            ks(&vec["challenges"])
                .iter()
                .map(|x| x.to_hex())
                .collect::<Vec<_>>(),
            hexes(&rs),
            "degree {degree} challenges"
        );
        assert_eq!(
            ks(&vec["table_evals"])
                .iter()
                .map(|x| x.to_hex())
                .collect::<Vec<_>>(),
            hexes(&evals),
            "degree {degree} table evals"
        );

        // Verifier on the vector's own proof yields the same point and the
        // recorded final claim.
        let vec_proof = SumcheckProof {
            round_msgs: vec["round_msgs"]
                .as_array()
                .unwrap()
                .iter()
                .map(ks)
                .collect(),
        };
        let mut vt = Transcript::new_default(protocol_label);
        let (r, final_claim) =
            sumcheck_verify(claim, num_vars, degree, &vec_proof, &mut vt, label).unwrap();
        assert_eq!(hexes(&rs), hexes(&r), "degree {degree} verifier point");
        assert_eq!(
            k(&vec["final_claim"]).to_hex(),
            final_claim.to_hex(),
            "degree {degree} final claim"
        );
        assert_eq!(f(&evals).to_hex(), final_claim.to_hex(), "degree {degree}");
    }
}
